        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z"/></svg>
      </div>
      <div>
        <h3 class="text-lg font-bold text-amber-900 mb-2">Key Point</h3>
        <p class="text-amber-800 text-lg">The contact record helps you understand the person, not just store their information.</p>
      </div>
    </div>
  </div>

  <!-- Action Steps -->
  <div class="bg-gradient-to-br from-emerald-50 to-teal-50 rounded-2xl p-6 border-2 border-emerald-200">
    <div class="flex items-center gap-3 mb-5">
      <div class="w-12 h-12 rounded-xl bg-emerald-100 flex items-center justify-center">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
      </div>
      <h3 class="text-xl font-bold text-emerald-900">Action Steps — Understand Key Contact Details</h3>
    </div>
    
    <div class="space-y-4">
      
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Open a sample contact</p>
          <p class="text-slate-600 text-sm">Click on any contact''s name to view their record</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Review basic details</p>
          <p class="text-slate-600 text-sm">Check name, email, and phone information</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Check tags and status</p>
          <p class="text-slate-600 text-sm">See how the contact is labeled and categorized</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">4</div>
        <div>
          <p class="font-semibold text-slate-900">Review activity</p>
          <p class="text-slate-600 text-sm">Look at notes, conversations, and appointments</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">5</div>
        <div>
          <p class="font-semibold text-slate-900">Ask the key question</p>
          <p class="text-slate-600 text-sm">What does this contact need next?</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Open a Contact Record',
      lesson_number = 3,
      sort_order = 3,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Open a Contact Record';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Open a Contact Record

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 2 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 2 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'open-contact-record' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson open-contact-record not found in module 2';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does a contact record help you understand?', 
    '[{"id":1,"text":"Only their email address","is_correct":false},{"id":2,"text":"Who the person is, where they came from, what activity has happened, and what they may need next","is_correct":true},{"id":3,"text":"Just their phone number","is_correct":false},{"id":4,"text":"Only their appointment history","is_correct":false}]'::jsonb,
    'A contact record tells the complete story of a person - who they are, where they came from, what conversations have happened, and what they need next.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How do you open a contact record?', 
    '[{"id":1,"text":"Send them an email first","is_correct":false},{"id":2,"text":"Click on the contact''s name in the Contacts list","is_correct":true},{"id":3,"text":"Call them on the phone","is_correct":false},{"id":4,"text":"Wait for them to contact you","is_correct":false}]'::jsonb,
    'To open a contact record, simply click on the contact''s name in the Contacts list.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What information is typically found inside a contact record?', 
    '[{"id":1,"text":"Only the person''s name","is_correct":false},{"id":2,"text":"Name, email, phone, tags, status, activity history, and more","is_correct":true},{"id":3,"text":"Your company''s financial data","is_correct":false},{"id":4,"text":"Other people''s contact records","is_correct":false}]'::jsonb,
    'A contact record contains comprehensive information including basic details, tags, status, assignment, and activity history like notes and conversations.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
